INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('c4fcd917-1c66-540c-b2be-c6b089e7ef87', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Finezja Compact', 'PL', 50.32, 35, 'Dom o wymiarach 5 × 7 m z zadaszonym patio, spełniający parametry budynku mieszkalnego. Dwuspadowy dach o nachyleniu 35°, trapezowe okna i elewacja z jasnej deski lub deski palonej japońską metodą Shou Sugi Ban. Na parterze salon, kuchnia, hol i łazienka, na poddaszu dwa pokoje, korytarz i WC, razem ok. 50 m² (56,6 m² po podłodze) powierzchni użytkowej. Patio o powierzchni 34,77 m² jest dostępne jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 3, 2, 1, 2, '7 × 5 m', 'Dwuspadowy, nachylenie 35°, wysokość do kalenicy 6,33 m; pokrycie: panel na rąbek', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (baliki 42 × 135 mm, ruszt 42 × 150 mm), ściany ocieplone wełną mineralną 150 mm, dach 200 mm', 'W cenie stopy fundamentowe. Opcjonalnie płyta fundamentowa zimna lub w pełni izolowana.', 'Dopłaty za patio, deskę palona metodą Shou Sugi Ban, gruntowanie i malowanie elewacji, wygłuszenie stropu, schody zabiegowe, płytę fundamentową zimną lub w pełni izolowaną oraz siatkę przeciw gryzoniom. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:15.447Z'::timestamptz, '2026-10-09T07:04:43.227Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: podłoga 150 mm, dach 200 mm, ściany 150 mm (λ = 0,033 W/(mK)).","ventilation":"inna","wallBuildUp":"Baliki drewniane 42 × 135 mm, membrana wysokoparoprzepuszczalna, ruszt drewniany 42 × 150 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), membrana, łaty 25 × 45 mm, deska elewacyjna 20 mm, łata stalowa perforowana przeciwgryzoniowa.","windowClass":"Stolarka okienna trzyszybowa w kolorze białym; drzwi zewnętrzne spełniające parametry budynku mieszkalnego.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","ventilationOther":"Brak danych w ofercie.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"finezja-compact-room-1","name":"Wiatrołap","areaM2":3.29,"floorLevel":"parter"},{"id":"finezja-compact-room-2","name":"Kuchnia","areaM2":3.81,"floorLevel":"parter"},{"id":"finezja-compact-room-3","name":"Łazienka","areaM2":3.53,"floorLevel":"parter"},{"id":"finezja-compact-room-4","name":"Salon","areaM2":17.51,"floorLevel":"parter"},{"id":"finezja-compact-room-5","name":"Pokój","areaM2":8.16,"floorLevel":"poddasze"},{"id":"finezja-compact-room-6","name":"Pokój","areaM2":8.8,"floorLevel":"poddasze"},{"id":"finezja-compact-room-7","name":"Korytarz","areaM2":3.61,"floorLevel":"poddasze"},{"id":"finezja-compact-room-8","name":"WC","areaM2":1.61,"floorLevel":"poddasze"}]'::jsonb, '[{"id":"finezja-compact-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"finezja-compact-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"finezja-compact-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"finezja-compact-faq-4","answer":"W technologii producenta nie ma potrzeby wykańczania ścian, podłóg ani sufitów. Wygłuszenie stropu jest dostępne jako opcja.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"finezja-compact-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"finezja-compact-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"finezja-compact-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"finezja-compact-req-2","key":"formalnosci","label":"Formalności","custom":false},{"id":"finezja-compact-req-3","key":null,"label":"Impregnacja zewnętrzna budynku we własnym zakresie lub zlecona firmie","custom":true}]'::jsonb, NULL, 'logbar-finezja-compact') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('95e22f8e-8d37-5d54-9c5c-efb15cd81803', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Lord', 'PL', 50.58, 35, 'Prosty dom o wymiarach 5 × 7 m z tarasem (22,92 m²) i pergolą, spełniający parametry budynku mieszkalnego. Dwuspadowy dach o nachyleniu 30°, duże okna wychodzące na taras i elewacja z jasnej deski lub deski palonej japońską metodą Shou Sugi Ban w duchu nowoczesnej stodoły. Na parterze wiatrołap, kuchnia, łazienka i salon, na poddaszu niezależny pokój i pokój otwarty; razem ok. 51 m² powierzchni użytkowej.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 3, 2, 1, 2, '7 × 5 m', 'Dwuspadowy, nachylenie 30°, wysokość do kalenicy 6,05 m, ścianka kolankowa 1,67 m; pokrycie: blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (baliki 42 × 135 mm, ruszt 42 × 150 mm), ściany ocieplone wełną mineralną 150 mm, dach 200 mm', 'W cenie stopy fundamentowe. Opcjonalnie płyta fundamentowa zimna lub w pełni izolowana.', 'Dopłaty za deskę palona metodą Shou Sugi Ban, gruntowanie i malowanie elewacji, wygłuszenie stropu, schody, płytę fundamentową zimną lub w pełni izolowaną oraz siatkę przeciw gryzoniom. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:15.708Z'::timestamptz, '2026-10-09T07:04:43.467Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: podłoga 150 mm, dach 200 mm, ściany 150 mm (λ = 0,033 W/(mK)).","ventilation":"inna","wallBuildUp":"Baliki drewniane 42 × 135 mm, membrana wysokoparoprzepuszczalna, ruszt drewniany 42 × 150 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), membrana, łaty 25 × 45 mm, deska elewacyjna 20 mm, łata stalowa perforowana przeciwgryzoniowa.","windowClass":"Stolarka okienna trzyszybowa w kolorze białym; drzwi zewnętrzne spełniające parametry budynku mieszkalnego.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","ventilationOther":"Brak danych w ofercie.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"lord-room-1","name":"Wiatrołap","areaM2":3.29,"floorLevel":"parter"},{"id":"lord-room-2","name":"Kuchnia","areaM2":3.81,"floorLevel":"parter"},{"id":"lord-room-3","name":"Łazienka","areaM2":3.53,"floorLevel":"parter"},{"id":"lord-room-4","name":"Salon","areaM2":17.51,"floorLevel":"parter"},{"id":"lord-room-5","name":"Korytarz","areaM2":1.16,"floorLevel":"poddasze"},{"id":"lord-room-6","name":"Pokój","areaM2":8.8,"floorLevel":"poddasze"},{"id":"lord-room-7","name":"Pokój","areaM2":12.48,"floorLevel":"poddasze"}]'::jsonb, '[{"id":"lord-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"lord-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"lord-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"lord-faq-4","answer":"W technologii producenta nie ma potrzeby wykańczania ścian, podłóg ani sufitów. Wygłuszenie stropu jest dostępne jako opcja.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"lord-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"lord-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"lord-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"lord-req-2","key":"formalnosci","label":"Formalności","custom":false},{"id":"lord-req-3","key":null,"label":"Impregnacja zewnętrzna budynku we własnym zakresie lub zlecona firmie","custom":true}]'::jsonb, NULL, 'logbar-lord') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('234243b6-4876-5fdd-a263-45c0d478f6fc', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Monako 111 A', 'PL', 87.75, 82.89, 'Nowoczesny dom o powierzchni zabudowy 82,89 m² (11,68 × 7,1 m) z dużymi przeszkleniami w szczycie. Parter 55,38 m² z salonem z aneksem kuchennym, dwoma pokojami i łazienką oraz piętro 32,37 m² z dwoma pokojami i łazienką, razem ok. 88 m² powierzchni użytkowej (111 m² po podłodze). Dwuspadowy dach pod kątem 40°, taras zadaszony 12,63 m² w bryle domu. Elewacja A: jasna deska elewacyjna profilowana z elementami z drewna opalanego Shou Sugi Ban. Taras niezadaszony 38,90 m² jest dostępny jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 5, 4, 2, 2, '11,68 × 7,1 m', 'Dwuspadowy, nachylenie 40°, wysokość do kalenicy 6,72 m; pokrycie: panel na rąbek stojący lub blachodachówka', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (słupy 45 × 145 mm), ściany ocieplone wełną mineralną 150 + 50 mm, dach 200 + 50 mm', 'W cenie stopy fundamentowe (podłoga na fundamencie punktowym, U = 0,184 W/(m²·K)). Opcjonalnie płyta fundamentowa w pełni izolowana (U = 0,180 W/(m²·K)) lub płyta przy posadzce betonowej po stronie inwestora.', 'Dopłaty za taras niezadaszony, gruntowanie i malowanie elewacji, schody zabiegowe oraz płytę fundamentową w pełni izolowaną ze stopami pod wykuszem. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:14.071Z'::timestamptz, '2026-10-09T07:04:42.087Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: ściany 150 + 50 mm, dach 200 + 50 mm (Uc = 0,148 W/(m²·K)), strop 150 mm, podłoga 150 mm; płyta fundamentowa z EPS grafitowym 50 mm i XPS 100 mm (Uc = 0,180 W/(m²·K)) lub podłoga na stopach (Uc = 0,184 W/(m²·K)).","ventilation":"grawitacyjna","wallBuildUp":"Deska elewacyjna 20 mm na wentylowanej szczelinie (łaty 25 × 40 mm), membrana wiatroizolacyjna, płyta MFP 12 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), konstrukcja słupowa C24 45 × 145 mm, membrana paroszczelna, wełna mineralna 50 mm w ruszcie instalacyjnym 40 × 60 mm, wykończenie deską boazeryjną lub płytą G-K Riduro. Współczynnik przenikania ciepła ściany Uc = 0,195 W/(m²·K).","windowClass":"Stolarka okienna trzyszybowa w kolorze grafitowym; stalowe drzwi zewnętrzne w kolorze grafitowym.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"monako-111-a-room-1","name":"Korytarz","areaM2":7.86,"floorLevel":"parter"},{"id":"monako-111-a-room-2","name":"Pokój","areaM2":8.55,"floorLevel":"parter"},{"id":"monako-111-a-room-3","name":"Pokój","areaM2":8.59,"floorLevel":"parter"},{"id":"monako-111-a-room-4","name":"Łazienka","areaM2":5.12,"floorLevel":"parter"},{"id":"monako-111-a-room-5","name":"Salon z aneksem kuchennym","areaM2":25.26,"floorLevel":"parter"},{"id":"monako-111-a-room-6","name":"Korytarz","areaM2":3.17,"floorLevel":"pietro"},{"id":"monako-111-a-room-7","name":"Pokój","areaM2":14.41,"floorLevel":"pietro"},{"id":"monako-111-a-room-8","name":"Łazienka","areaM2":1.05,"floorLevel":"pietro"},{"id":"monako-111-a-room-9","name":"Pokój","areaM2":13.73,"floorLevel":"pietro"}]'::jsonb, '[{"id":"monako-111-a-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"monako-111-a-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"monako-111-a-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"monako-111-a-faq-4","answer":"W standardzie z wykończeniem wnętrz ściany i strop są wykończone deską boazeryjną lub płytą G-K, a podłoga ma suchy jastrych, więc nie trzeba ich wykańczać. W stanie surowym zamkniętym (SSZ) tych prac nie ma w cenie.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"monako-111-a-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"monako-111-a-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek lub blachodachówki, orynnowanie, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"monako-111-a-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"monako-111-a-req-2","key":"miejsce-dla-dzwigu","label":"Miejsce dla dźwigu","custom":false},{"id":"monako-111-a-req-3","key":"formalnosci","label":"Formalności","custom":false}]'::jsonb, NULL, 'logbar-monako-111-a') ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug") VALUES ('f29ca9a4-5ac5-54b0-8d28-7ba37c6e5de6', 'ee7266d7-bf04-522e-82c3-67e925060fa5', 'published', 'Logbar Finezja', 'PL', 49.62, 35, 'Dom o wymiarach 5 × 7 m z zadaszonym patio, spełniający parametry budynku mieszkalnego. Dwuspadowy dach o nachyleniu 35°, trapezowe okna i elewacja z jasnej deski lub deski palonej japońską metodą Shou Sugi Ban. Na parterze salon, kuchnia, hol i łazienka, na poddaszu dwa pokoje i korytarz, razem ok. 50 m² (57,3 m² po podłodze) powierzchni użytkowej. Patio o powierzchni 34,77 m² jest dostępne jako opcja.', 'deweloperski', NULL, NULL, NULL, NULL, NULL, NULL, 10, 'caloroczny', 3, 2, 1, 2, '7 × 5 m', 'Dwuspadowy, nachylenie 35°, wysokość do kalenicy 6,33 m; pokrycie: panel na rąbek', 'Szkielet drewniany z drewna konstrukcyjnego klasy C24 (baliki 42 × 135 mm, ruszt 42 × 150 mm), ściany ocieplone wełną mineralną 150 mm, dach 200 mm', 'W cenie stopy fundamentowe. Opcjonalnie płyta fundamentowa zimna lub w pełni izolowana.', 'Dopłaty za patio, deskę palona metodą Shou Sugi Ban, gruntowanie i malowanie elewacji, wygłuszenie stropu, schody zabiegowe, płytę fundamentową zimną lub w pełni izolowaną oraz siatkę przeciw gryzoniom. Dopłata do ram okiennych w innym kolorze.', 'EUR', NULL, NULL, false, '2026-10-09T06:28:15.182Z'::timestamptz, '2026-10-09T07:04:43.007Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna: podłoga 150 mm, dach 200 mm, ściany 150 mm (λ = 0,033 W/(mK)).","ventilation":"inna","wallBuildUp":"Baliki drewniane 42 × 135 mm, membrana wysokoparoprzepuszczalna, ruszt drewniany 42 × 150 mm, wełna mineralna 150 mm λ = 0,033 W/(mK), membrana, łaty 25 × 45 mm, deska elewacyjna 20 mm, łata stalowa perforowana przeciwgryzoniowa.","windowClass":"Stolarka okienna trzyszybowa w kolorze białym; drzwi zewnętrzne spełniające parametry budynku mieszkalnego.","heatSourceOther":"Źródło ciepła nie jest określone w ofercie producenta.","ventilationOther":"Brak danych w ofercie.","constructionTechnology":"szkielet-drewniany","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, 2, 'Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.', NULL, NULL, NULL, '[{"id":"finezja-room-1","name":"Wiatrołap","areaM2":3.29,"floorLevel":"parter"},{"id":"finezja-room-2","name":"Kuchnia","areaM2":3.81,"floorLevel":"parter"},{"id":"finezja-room-3","name":"Łazienka","areaM2":3.53,"floorLevel":"parter"},{"id":"finezja-room-4","name":"Salon","areaM2":17.51,"floorLevel":"parter"},{"id":"finezja-room-5","name":"Pokój","areaM2":12.48,"floorLevel":"poddasze"},{"id":"finezja-room-6","name":"Pokój","areaM2":8.8,"floorLevel":"poddasze"},{"id":"finezja-room-7","name":"Korytarz","areaM2":1.4,"floorLevel":"poddasze"}]'::jsonb, '[{"id":"finezja-faq-1","answer":"Nie. Do ceny należy doliczyć koszt transportu oraz dźwigu do miejsca montażu. W cenę nie jest wliczony projekt architektoniczno-budowlany.","question":"Czy cena zawiera transport, dźwig i projekt budowlany?"},{"id":"finezja-faq-2","answer":"Tak, wszystkie ceny z oferty producenta są cenami netto. Stawka VAT zależy od przeznaczenia budynku.","question":"Czy podane ceny są cenami netto?"},{"id":"finezja-faq-3","answer":"Producent udziela gwarancji na 24 miesiące na całość domu oraz na 10 lat na konstrukcję.","question":"Jaka jest gwarancja?"},{"id":"finezja-faq-4","answer":"W technologii producenta nie ma potrzeby wykańczania ścian, podłóg ani sufitów. Wygłuszenie stropu jest dostępne jako opcja.","question":"Czy po montażu trzeba wykańczać wnętrza?"},{"id":"finezja-faq-5","answer":"Tak, za dopłatą. Producent podaje jej wysokość w indywidualnej wycenie.","question":"Czy ramy okienne mogą mieć inny kolor?"},{"id":"finezja-faq-6","answer":"Zakres prac obejmuje montaż domu, montaż stóp fundamentowych, wykonanie izolacji termicznej ścian zewnętrznych, podłogi i dachu, położenie paneli dachowych na rąbek, montaż stolarki okiennej i drzwi zewnętrznych, rozprowadzenie instalacji elektrycznej i wodno-kanalizacyjnej oraz wykonanie elewacji.","question":"Co obejmuje zakres prac producenta?"}]'::jsonb, NULL, '[{"id":"finezja-req-1","key":"dojazd-dla-transportu","label":"Dojazd dla transportu","custom":false},{"id":"finezja-req-2","key":"formalnosci","label":"Formalności","custom":false},{"id":"finezja-req-3","key":null,"label":"Impregnacja zewnętrzna budynku we własnym zakresie lub zlecona firmie","custom":true}]'::jsonb, NULL, 'logbar-finezja') ON CONFLICT DO NOTHING;
