INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('0072d441-d110-4617-9af3-046c702bc6ca', '4610927e-0d5a-573f-9e6a-6dface1cac9a', 'en', 'Closed shell (SSZ): the same scope as the finished-interior standard, but without the dry-screed floor and without finishing the walls and ceilings with tongue-and-groove boards or plasterboard.', '2026-10-09T06:28:14.127Z'::timestamptz, '2026-10-09T07:04:52.701Z'::timestamptz, 'The dry-screed floor, finishing of walls and ceilings with tongue-and-groove boards or plasterboard, transport, a crane at the assembly site and the architectural and building design.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('9ca595d6-f21a-43a3-b527-b4f4c4569485', '4610927e-0d5a-573f-9e6a-6dface1cac9a', 'de', 'Rohbau geschlossen (SSZ): Leistungsumfang wie beim Standard mit Innenausbau, jedoch ohne Trockenestrich und ohne Wand- und Deckenverkleidung aus Profilholz oder Gipskartonplatten.', '2026-10-09T06:28:14.127Z'::timestamptz, '2026-10-09T07:04:52.701Z'::timestamptz, 'Trockenestrich, Wand- und Deckenverkleidung aus Profilholz oder Gipskartonplatten, Transport, ein Kran am Montageort und die Architektur- und Bauplanung.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('570c3b1c-7d0e-4f61-9722-73a92fa961bd', '4610927e-0d5a-573f-9e6a-6dface1cac9a', 'nl', 'Casco dicht (SSZ): hetzelfde pakket als de afbouwstandaard, maar zonder droge dekvloer en zonder afwerking van wanden en plafonds met profielplanken of gipsplaten.', '2026-10-09T06:28:14.127Z'::timestamptz, '2026-10-09T07:04:52.701Z'::timestamptz, 'De droge dekvloer, afwerking van wanden en plafonds met profielplanken of gipsplaten, transport, een kraan op de montagelocatie en het architectonisch en bouwkundig ontwerp.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('2f6f977f-4062-47e5-ba23-37b6ab52e6c1', 'e31fd361-bbf2-56fb-8f44-8ace23d02394', 'en', 'Finished-interior standard: the house is fully completed on the outside, with foundation pads, sound-deadening of the ceiling, a floor covered with dry screed, walls and ceiling finished with tongue-and-groove boards or plasterboard, temporary stairs, a roof window in the attic bathroom, and electrical (50 points) and water and sewage (14 points) installations.', '2026-10-09T06:28:14.127Z'::timestamptz, '2026-10-09T07:04:52.702Z'::timestamptz, 'Transport, a crane at the assembly site and the architectural and building design.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('1005a4ac-8931-482e-b619-38f20fc38a77', 'e31fd361-bbf2-56fb-8f44-8ace23d02394', 'de', 'Standard mit Innenausbau: Das Haus ist außen komplett fertiggestellt, mit Punktfundamenten, Schalldämmung der Decke, Trockenestrich im Boden, Wänden und Decke aus Profilholz oder Gipskartonplatten, provisorischer Treppe, einem Dachfenster im Bad im Dachgeschoss, sowie Elektro- (50 Punkte) und Wasser-/Abwasserinstallation (14 Punkte).', '2026-10-09T06:28:14.127Z'::timestamptz, '2026-10-09T07:04:52.702Z'::timestamptz, 'Transport, ein Kran am Montageort und die Architektur- und Bauplanung.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('bebbad09-35e0-467b-8f52-cecc47d9c299', 'ad090f1e-c260-5342-b7e2-d9c3c776a9a0', 'en', 'Interior-in-timber standard: foundation pads and temporary stairs are included in the price. In the producer''s technology there is no need to finish the walls, floors or ceilings.', '2026-10-09T06:28:15.270Z'::timestamptz, '2026-10-09T07:04:53.637Z'::timestamptz, 'Transport to the assembly site, the architectural and building design and the external impregnation of the building.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_variant_translation" ("id", "product_variant_id", "locale", "scope_summary", "created_at", "updated_at", "excluded_scope", "variant_label") VALUES ('87e73adf-9b7b-41d5-910c-cb785c2072bf', 'ad090f1e-c260-5342-b7e2-d9c3c776a9a0', 'de', 'Standard mit Innenräumen aus Holz: Punktfundamente und provisorische Treppe sind im Preis enthalten. In der Technologie des Herstellers müssen Wände, Böden und Decken nicht ausgebaut werden.', '2026-10-09T06:28:15.270Z'::timestamptz, '2026-10-09T07:04:53.637Z'::timestamptz, 'Transport zum Montageort, die Architektur- und Bauplanung sowie die Außenimprägnierung des Gebäudes.', NULL) ON CONFLICT DO NOTHING;
